    @Override
    public BigDecimal frete(Pedido pedido) {
        return Dinheiro.centavos(FIXO.add(POR_KG.multiply(pedido.pesoKg())));
    }

    @Override
    public int prazoDias(Pedido pedido) {
        return 7;
    }
}
